import { Schema, model } from 'mongoose';

// ─────────────────────────────────────────────────────────────────────────────
//  SYNTHETIC DEMONSTRATION DATA — NOT REAL SALES.
//  Generated by `npm run seed:ai-demo` so the forecasting model can be developed and
//  demonstrated before Cartify has enough real order history. Forecasts trained on this
//  collection are flagged `dataSource: 'synthetic_demo'` and labelled in every UI.
//  Real sales always come from the `orders` collection.
// ─────────────────────────────────────────────────────────────────────────────
const syntheticSaleSchema = new Schema(
  {
    source:       { type: String, enum: ['synthetic_demo'], default: 'synthetic_demo', required: true },
    datasetId:    { type: String, required: true, index: true },
    date:         { type: Date, required: true },           // UTC day
    productId:    { type: Schema.Types.ObjectId, ref: 'product', required: true },
    branchId:     { type: Schema.Types.ObjectId, ref: 'branch', default: null }, // null = online store
    unitsSold:    { type: Number, required: true, min: 0 },
    unitPrice:    { type: Number, required: true, min: 0 },
    discount:     { type: Number, default: 0, min: 0, max: 100 },
    closingStock: { type: Number, required: true, min: 0 },
    inStock:      { type: Boolean, required: true },         // false = sold out that day (sales are censored)
    latentDemand: { type: Number, min: 0 },                  // simulated true demand; offline evaluation only
  },
  { versionKey: false }
);

syntheticSaleSchema.index({ productId: 1, branchId: 1, date: 1 });
syntheticSaleSchema.index({ branchId: 1, date: 1 });

export default model('syntheticSale', syntheticSaleSchema);
